@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(32.7 57.9% 96.3%);
  --color-foreground: hsl(24.8 32.6% 17.5%);
  --color-card: hsl(33.3 100.0% 98.2%);
  --color-card-foreground: hsl(24.8 32.6% 17.5%);
  --color-popover: hsl(33.3 100.0% 98.2%);
  --color-popover-foreground: hsl(24.8 32.6% 17.5%);
  --color-primary: hsl(23.3 59.5% 33.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(30.0 40.5% 85.5%);
  --color-secondary-foreground: hsl(24.8 32.6% 17.5%);
  --color-muted: hsl(30.0 40.5% 85.5%);
  --color-muted-foreground: hsl(25.5 19.8% 53.5%);
  --color-accent: hsl(30.9 67.3% 90.4%);
  --color-accent-foreground: hsl(25.6 64.9% 29.0%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(31.0 40.8% 86.1%);
  --color-input: hsl(29.3 38.7% 78.2%);
  --color-ring: hsl(23.3 59.5% 33.9%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(32.7 57.9% 96.3%);
  --color-foreground: hsl(24.8 32.6% 17.5%);
  --color-card: hsl(33.3 100.0% 98.2%);
  --color-card-foreground: hsl(24.8 32.6% 17.5%);
  --color-popover: hsl(33.3 100.0% 98.2%);
  --color-popover-foreground: hsl(24.8 32.6% 17.5%);
  --color-primary: hsl(23.3 59.5% 33.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(30.0 40.5% 85.5%);
  --color-secondary-foreground: hsl(24.8 32.6% 17.5%);
  --color-muted: hsl(30.0 40.5% 85.5%);
  --color-muted-foreground: hsl(25.5 19.8% 53.5%);
  --color-accent: hsl(30.9 67.3% 90.4%);
  --color-accent-foreground: hsl(25.6 64.9% 29.0%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(31.0 40.8% 86.1%);
  --color-input: hsl(29.3 38.7% 78.2%);
  --color-ring: hsl(23.3 59.5% 33.9%);
    }

    @variant dark {
  --color-background: hsl(25.7 36.8% 7.5%);
  --color-foreground: hsl(29.2 50.7% 85.7%);
  --color-card: hsl(24.0 32.5% 15.1%);
  --color-card-foreground: hsl(29.2 50.7% 85.7%);
  --color-popover: hsl(24.7 34.7% 9.6%);
  --color-popover-foreground: hsl(29.2 50.7% 85.7%);
  --color-primary: hsl(27.7 58.0% 56.1%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(24.5 34.4% 12.5%);
  --color-secondary-foreground: hsl(29.2 50.7% 85.7%);
  --color-muted: hsl(24.5 34.4% 12.5%);
  --color-muted-foreground: hsl(29.4 22.3% 44.9%);
  --color-accent: hsl(27.1 40.3% 15.1%);
  --color-accent-foreground: hsl(29.0 79.7% 71.0%);
  --color-destructive: hsl(4.6 65.6% 64.7%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(24.0 32.5% 15.1%);
  --color-input: hsl(26.2 35.8% 21.4%);
  --color-ring: hsl(27.7 58.0% 56.1%);
    }
  }
}
